<?php
namespace App\Http\Controllers;
use App\Models\LanguageDiscountPolicy; use App\Support\{CenterCode,ExcelExporter}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class LanguageDiscountController extends Controller {public function index(Request $r):View{$q=LanguageDiscountPolicy::latest();if($r->filled('q')){$s=$r->string('q');$q->where(fn($b)=>$b->where('name','like',"%$s%")->orWhere('eligible_subject','like',"%$s%"));}return view('language.discounts.index',['items'=>$q->paginate(\App\Support\Pagination::perPage())->withQueryString()]);}public function create():View{return view('language.discounts.form',['item'=>new LanguageDiscountPolicy]);}public function store(Request $r):RedirectResponse{$d=$this->data($r);$d['code']=CenterCode::next('language_discount_policies','MG');LanguageDiscountPolicy::create($d);return redirect()->route('language-discounts.index')->with('success','Đã thêm chế độ miễn giảm.');}public function edit(LanguageDiscountPolicy $languageDiscount):View{return view('language.discounts.form',['item'=>$languageDiscount]);}public function update(Request $r,LanguageDiscountPolicy $languageDiscount):RedirectResponse{$languageDiscount->update($this->data($r));return redirect()->route('language-discounts.index')->with('success','Đã cập nhật chế độ miễn giảm.');}public function destroy(LanguageDiscountPolicy $languageDiscount):RedirectResponse{$languageDiscount->delete();return back()->with('success','Đã xóa chế độ miễn giảm.');}public function export(){return ExcelExporter::download('che-do-mien-giam-'.date('Ymd').'.xlsx',['Mã','Tên chế độ','Giảm %','Đối tượng','Từ ngày','Đến ngày','Trạng thái'],LanguageDiscountPolicy::withTrashed()->get()->map(fn($i)=>[$i->code,$i->name,$i->percentage,$i->eligible_subject,$i->starts_at?->format('d/m/Y'),$i->ends_at?->format('d/m/Y'),$i->active?'Hoạt động':'Ngừng']));}private function data(Request $r):array{$d=$r->validate(['name'=>'required|max:255','percentage'=>'required|numeric|min:0|max:100','eligible_subject'=>'required|max:255','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','note'=>'nullable']);$d['active']=$r->boolean('active');return $d;} }
